var e={id:`fire-slags-joder`,episode:19,door:19,title:{nb:`Fire slags jøder`,en:`Four kinds of Jews`},reference:`Luk 20,27–40; Apg 23,6–8`,place:`jerusalem`,prologue:[{image:`maps/jerusalem-gate.webp`,text:{nb:`Teofilos er greker. Når Lukas skriver «fariseer» og «saddukeer», må han forklare. Du har hørt dem ved templet før; nå må Lukas finne ut hva som skiller dem.`,en:`Theophilus is a Greek. When Luke writes “Pharisee” and “Sadducee”, he must explain. You heard them by the temple before; now Luke must work out what divides them.`}},{image:`art/lukas.webp`,text:{nb:`Fire slags jøder, sier Josefus, en ung prest i Jerusalem. Og mange står utenfor alle fire. Hvor passet Jesus inn?`,en:`Four kinds of Jews, says Josephus, a young priest in Jerusalem. And many stand outside all four. Where did Jesus fit in?`}}],intro:{nb:`Tempelforgården i Jerusalem, full av folk av alle slag.`,en:`The temple court in Jerusalem, full of people of every kind.`},outro:{nb:`Prøv vitnene mot en annen kilde: de stemmer med Josefus. Og spør hvem som kunne funnet på ham: ingen av flokkene ville laget en slik Messias.`,en:`Test the witnesses against another source: they fit Josephus. And ask who could have invented him: none of the groups would have made such a Messiah.`},map:[`################################`,`################################`,`################################`,`################################`,`##########.##########.##########`,`#########.............##########`,`##############...###############`,`###############..###############`,`###############..###############`,`##############....##############`,`##############....##############`,`####.........................###`,`####........................####`,`####........................####`,`#######.....................####`,`#########...........############`,`##########..........############`,`##########..........############`,`########.#..........############`,`########............############`,`########............############`],background:`jerusalem-tempel.webp`,mood:`tense`,areas:[{id:`raadskammer`,map:[`################################`,`################################`,`################################`,`################################`,`################################`,`################################`,`################################`,`######......########......######`,`######......########......######`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#############......#############`,`#############......#############`,`#############......#############`,`#############......#############`,`################################`,`################################`,`################################`],background:`prestens-hus.webp`,scale:1.8,ambience:`temple`},{id:`skriverkammer`,map:[`################################`,`################################`,`################################`,`################################`,`################################`,`################################`,`################################`,`######......########......######`,`######......########......######`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#############......#############`,`#############......#############`,`#############......#############`,`################################`,`################################`,`################################`],background:`tempelkammer.webp`,scale:1.8,ambience:`temple`}],start:{x:11,y:5},entities:[{id:`lukas`,kind:`person`,x:9,y:5,name:{nb:`Lukas`,en:`Luke`},look:`luke`,portrait:`lukas.webp`,interactions:[{not:[`oppdrag`],say:[{nb:`Hør fariseeren, saddukeeren, esseneren og den unge ved porten. Så tolleren, samaritanen og grekeren. Til slutt rådskammeret og skriverkammeret.`,en:`Hear the Pharisee, the Sadducee, the Essene and the young man. Then the tax collector, the Samaritan and the Greek. Last, the council and scribe’s chambers.`}],set:[`oppdrag`]},{has:[`fire-lost`,`oppstandelsen-lost`,`de-andre-lost`,`mot-josefus-lost`,`passet-ikke-lost`,`raadet-lost`],not:[`avsluttet`],say:[{nb:`Nå forstår jeg stridene bedre: om oppstandelsen, om sabbaten, om hvem som får sitte til bords.`,en:`Now I understand the quarrels better: the resurrection, the sabbath, who may sit at table.`},{nb:`I morgen legger vi det jeg skriver ved siden av det menigheten i Antiokia forteller om fødselen.`,en:`Tomorrow we lay what I write beside what the church in Antioch says about the birth.`}],set:[`avsluttet`]},{has:[`spor:josefus`],not:[`fire-lost`],say:[{nb:`Sakene venter i vitneboka.`,en:`The cases are waiting in the notebook.`}]},{say:[{nb:`Fariseeren, saddukeeren, esseneren, den unge. Tolleren, samaritanen, grekeren. Rådskammeret og skriverkammeret.`,en:`The Pharisee, the Sadducee, the Essene, the young man. The tax collector, the Samaritan, the Greek. The council chamber and the scribe’s chamber.`}]}]},{id:`dor-raadskammer`,kind:`place`,x:10,y:4,name:{nb:`Rådskammeret`,en:`The council chamber`},look:`hotspot`,door:{area:`raadskammer`,x:15,y:14}},{id:`dor-skriverkammer`,kind:`place`,x:21,y:4,name:{nb:`Skriverkammeret`,en:`The scribe’s chamber`},look:`hotspot`,door:{area:`skriverkammer`,x:15,y:14}},{id:`fariseer`,kind:`person`,x:14,y:6,name:{nb:`Fariseeren`,en:`The Pharisee`},look:`scribe`,portrait:`scribe.webp`,interactions:[{has:[`oppdrag`],not:[`spor:fariseer`],say:[{nb:`Vi er de atskilte, det betyr navnet. Vi holder loven med gjerder rundt: sabbaten, tienden, rene hender. Hele folket skal være hellig.`,en:`Our name means the separated ones. We keep the law with a fence around it: the sabbath, the tithe, clean hands. The whole people is to be holy.`},{nb:`Vi tror på oppstandelsen, på engler og på dommen, og folket hører på oss.`,en:`We believe in the resurrection, angels and the judgement, and the people listen to us.`},{nb:`Jesus fra Nasaret? Han spiste hos oss, og hos tollere. Han sa at vi vasket utsiden av begeret. Det sved. Noen av oss fulgte ham likevel.`,en:`Jesus of Nazareth? He ate with us, and with tax collectors. He said we washed only the outside of the cup. That stung. Yet some of us followed him.`}],set:[`spor:fariseer`,`spor:fariseer-jesus`,`fakta:fariseere`]},{has:[`innbydelser`],not:[`svar:fariseer`],say:[{nb:`Spise hos en toller? Aldri.`,en:`Eat at a tax collector’s? Never.`}],set:[`svar:fariseer`]},{not:[`oppdrag`],say:[{nb:`Snakk med Lukas først.`,en:`Speak with Luke first.`}]},{say:[{nb:`Hele folket skal være hellig. Ved hvert bord.`,en:`The whole people is to be holy. At every table.`}]}]},{id:`saddukeer`,kind:`person`,x:24,y:12,name:{nb:`Saddukeeren`,en:`The Sadducee`},look:`scribe`,portrait:`scribe.webp`,interactions:[{has:[`oppdrag`],not:[`spor:saddukeer`],say:[{nb:`Vi er prestefamiliene; templet er vårt. Moses’ fem bøker går foran alt, og fariseernes «fedrenes tradisjon» er menneskepåfunn.`,en:`We are the priestly families; the temple is ours. Moses’ five books come first; the Pharisees’ “tradition of the fathers” is human invention.`},{nb:`Oppstandelse? Det står ikke hos Moses. Engler og ånder: nei. Og vi holder fred med Roma, ellers mister vi templet.`,en:`Resurrection? It is not in Moses. Angels and spirits: no. And we keep peace with Rome, or we lose the temple.`},{nb:`Vi prøvde ham med en gåte om sju brødre og én kone. Han svarte fra tornebusken hos Moses: Abrahams Gud er ikke de dødes Gud. Vi hadde ikke noe svar.`,en:`We tested him with a riddle: seven brothers, one wife. He answered from the burning bush in Moses: Abraham’s God is not a God of the dead. We had no answer.`}],set:[`spor:saddukeer`,`spor:gaaten`,`fakta:saddukeere`]},{has:[`innbydelser`],not:[`svar:saddukeer`],say:[{nb:`Jeg bruker ham. Jeg spiser ikke med ham.`,en:`I use him. I do not eat with him.`}],set:[`svar:saddukeer`]},{say:[{nb:`Moses’ fem bøker. Og fred med Roma.`,en:`The five books of Moses. And peace with Rome.`}]}]},{id:`essener`,kind:`person`,x:17,y:12,name:{nb:`Esseneren`,en:`The Essene`},look:`beggar`,portrait:`beggar.webp`,interactions:[{has:[`oppdrag`],not:[`spor:essener`],say:[{nb:`Vi har forlatt templet, for prestene her er urene, og kalenderen deres er feil. Vi bor sammen, deler alt og renser oss hver dag.`,en:`We have left the temple: the priests here are impure and their calendar is wrong. We live together, share everything and wash every day.`},{nb:`Vi venter på to salvede, en prest og en konge. En spedalsk eller en lam får ikke sitte ved bordet vårt.`,en:`We wait for two anointed ones, a priest and a king. No leper or lame man may sit at our table.`},{nb:`Han fra Nasaret? Han rørte ved spedalske og kalte lamme og blinde til bords. Det motsatte av oss.`,en:`The one from Nazareth? He touched lepers and called the lame and the blind to the table. The opposite of us.`}],set:[`spor:essener`,`spor:essener-jesus`,`fakta:essenere`]},{has:[`innbydelser`],not:[`svar:essener`],say:[{nb:`Uren. Si ham det.`,en:`Unclean. Tell him so.`}],set:[`svar:essener`]},{has:[`spor:sol`,`spor:maane`],not:[`kalender-sett`],say:[{nb:`Derfor holder prestene høytidene på feil dag, etter vår regning.`,en:`That is why the priests keep the feasts on the wrong day, by our reckoning.`}],set:[`kalender-sett`]},{say:[{nb:`Renhet først. Han gjorde det motsatte.`,en:`Purity first. He did the opposite.`}]}]},{id:`ung`,kind:`person`,x:27,y:12,name:{nb:`Den unge ved porten`,en:`The young man at the gate`},look:`boy`,portrait:`boy.webp`,interactions:[{has:[`oppdrag`],not:[`spor:ung`],say:[{nb:`Ingen herre uten Gud. Judas fra Galilea sa det da keiseren ville telle oss. Å betale skatt til keiseren er å kalle ham herre.`,en:`No lord but God. Judas of Galilee said it when the emperor counted us. Paying tax to the emperor means calling him lord.`},{nb:`Vi venter ikke på salvede fra ørkenen. Vi venter på dagen vi tar sverdet.`,en:`We do not wait for anointed ones from the desert. We wait for the day we take the sword.`},{nb:`De spurte ham om skatten. Han så på keiserens bilde på mynten: gi keiseren det som er keiserens, og Gud det som er Guds. Hva han mente, vet jeg ikke.`,en:`They asked him about the tax. Looking at the emperor’s face on the coin, he said: give the emperor what is his, and God what is God’s. I do not know what he meant.`}],set:[`spor:ung`,`spor:skatten`,`fakta:fjerde`]},{has:[`innbydelser`],not:[`svar:ung`],say:[{nb:`Forræder. Han tar romernes penger.`,en:`Traitor. He takes the Romans’ money.`}],set:[`svar:ung`]},{say:[{nb:`Ingen herre uten Gud. Ikke keiseren.`,en:`No lord but God. Not the emperor.`}]}]},{id:`toller`,kind:`person`,x:12,y:12,name:{nb:`Tolleren`,en:`The tax collector`},look:`trader`,portrait:`trader.webp`,interactions:[{has:[`oppdrag`],not:[`spor:toller`],say:[{nb:`Jeg hører ikke til noen av dem. Fariseeren spiser ikke med meg, saddukeeren bruker meg, og den unge der vil drepe meg.`,en:`I belong to none of them. The Pharisee won’t eat with me, the Sadducee uses me, and that young man wants to kill me.`},{nb:`Så sa en til Levi i Kapernaum: følg meg, og spiste i huset hans med oss alle. Fariseerne spurte hvorfor. Han sa: de syke trenger lege.`,en:`Then someone said to Levi in Capernaum: follow me, and ate in his house with all of us. The Pharisees asked why. He said: the sick need a doctor.`}],set:[`spor:toller`]},{has:[`svar:fariseer`,`svar:saddukeer`,`svar:essener`,`svar:ung`],not:[`ingen-kom`],say:[{nb:`Ingen kom. Han kom.`,en:`None of them came. He came.`}],set:[`ingen-kom`]},{has:[`spor:toller`],not:[`innbydelser`],say:[{nb:`Fire innbydelser til bords hos meg. Bær dem til fariseeren, saddukeeren, esseneren og den unge ved porten, og hør svarene.`,en:`Four invitations to my table. Take them to the Pharisee, the Sadducee, the Essene and the young man at the gate, and hear their answers.`}],set:[`innbydelser`]},{say:[{nb:`De syke trenger lege. Det var oss.`,en:`The sick need a doctor. That was us.`}]}]},{id:`samaritan`,kind:`person`,x:5,y:11,name:{nb:`Samaritanen`,en:`The Samaritan`},look:`courier`,portrait:`courier.webp`,interactions:[{has:[`oppdrag`],not:[`spor:samaritan`],say:[{nb:`Vårt tempel sto på Garisim, til jødene rev det ned. Vi har bare Moses’ fem bøker, og jødene kaller oss fremmede.`,en:`Our temple stood on Gerizim until the Jews tore it down. We keep only Moses’ five books, and the Jews call us foreigners.`},{nb:`Han fra Nasaret gikk gjennom landet vårt. En landsby avviste ham, og disiplene ville rope ned ild. Han sa nei.`,en:`The one from Nazareth walked through our land. A village turned him away; his disciples wanted to call down fire. He said no.`},{nb:`Og han fortalte en historie der en samaritan var den gode.`,en:`And he told a story where a Samaritan was the good one.`}],set:[`spor:samaritan`,`fakta:samaritanere`]},{say:[{nb:`En samaritan var den gode. Det har jeg aldri hørt fra en jøde før.`,en:`A Samaritan was the good one. I have never heard that from a Jew before.`}]}]},{id:`greker`,kind:`person`,x:19,y:12,name:{nb:`Den gudfryktige grekeren`,en:`The God-fearing Greek`},look:`potter`,portrait:`potter.webp`,interactions:[{has:[`oppdrag`],not:[`spor:greker`],say:[{nb:`Jeg er greker og tror på Israels Gud, men jeg er ikke omskåret. Derfor stopper jeg ved gjerdet. Lenger inn venter døden.`,en:`I am a Greek who believes in the God of Israel, but I am not circumcised. So I must stop at the barrier out there, or die.`},{nb:`Teofilos er vel en av oss? Vi vil vite om det er plass for oss.`,en:`Theophilus is one of us, I suppose? We want to know if there is room for us.`}],set:[`spor:greker`,`fakta:gudfryktige`]},{say:[{nb:`Er det plass for oss? Det er spørsmålet.`,en:`Is there room for us? That is the question.`}]}]},{id:`gutt`,kind:`person`,x:14,y:11,name:{nb:`Jenta med stjernene`,en:`The girl with the stars`},look:`girl`,portrait:`girl.webp`,interactions:[{say:[{nb:`Kan du finne stjernene i rekkefølge? Bestefar sier esseneren teller dagene etter sola og presten etter månen, og at de krangler om hvilken dag det er påske.`,en:`Can you find the stars in order? Grandfather says the Essene counts the days by the sun and the priest by the moon, and that they quarrel about which day Passover is.`}],play:{game:`stars`,title:{nb:`Finn stjernene i rekkefølge`,en:`Find the stars in order`},win:`spill-stjerner`}}]},{id:`gjerdet`,kind:`thing`,x:16,y:11,name:{nb:`Gjerdet med innskriften`,en:`The barrier with the inscription`},look:`hotspot`,interactions:[{say:[{nb:`En lav mur rundt den indre forgården, med tavler på gresk og latin: ingen fremmed innenfor, og den som tas, har seg selv å takke for døden.`,en:`A low wall around the inner court, with signs in Greek and Latin: no foreigner beyond, and anyone caught has himself to blame for his death.`}],set:[`spor:gjerdet`]}]},{id:`vei-nasaret`,kind:`place`,x:4,y:13,name:{nb:`Veien til Nasaret`,en:`The road to Nazareth`},look:`hotspot`,travelTo:`nasaret`},{id:`vei-cesarea`,kind:`place`,x:14,y:20,name:{nb:`Veien til Cæsarea`,en:`The road to Caesarea`},look:`hotspot`,travelTo:`cesarea`},{id:`dor-ut-raadskammer`,kind:`place`,x:15,y:17,name:{nb:`Ut i forgården`,en:`Out to the court`},look:`hotspot`,door:{area:`main`,x:10,y:5},area:`raadskammer`},{id:`raadsherre`,kind:`person`,x:20,y:9,name:{nb:`Rådsherren`,en:`The councillor`},look:`james`,portrait:`james.webp`,interactions:[{has:[`oppdrag`],not:[`spor:raadsherre`],say:[{nb:`Det store rådet, Sanhedrin: øverstepresten, saddukeere fra prestefamiliene og fariseere blant de skriftlærde. Sjelden enige.`,en:`The great council, the Sanhedrin: the high priest, Sadducees from the priestly families, Pharisees among the scribes. Rarely agreed.`},{nb:`Da de forhørte Paulus her, splittet han dem med ett ord: oppstandelsen.`,en:`When they questioned Paul here, he split them with one word: the resurrection.`},{nb:`Men morgenen de dømte Jesus, sto øversteprestene, de eldste og de skriftlærde samlet. Prestene fryktet for templet og Roma.`,en:`But the morning they condemned Jesus, the chief priests, elders and scribes stood together; the priests feared for the temple and Rome.`},{nb:`Om fariseerne som flokk var med, vet jeg mindre; noen hadde advart ham. Og Josef fra Arimatea, en rådsherre, var imot dommen.`,en:`Whether the Pharisees as a group took part, I am less sure; some had warned him. And Joseph of Arimathea, a councillor, opposed the verdict.`}],set:[`spor:raadsherre`,`spor:raadet`]},{not:[`oppdrag`],say:[{nb:`Snakk med Lukas først.`,en:`Speak with Luke first.`}]},{say:[{nb:`Sjelden enige. Den morgenen var nesten alle det.`,en:`Seldom in agreement. That morning nearly all of them were.`}]}],area:`raadskammer`},{id:`benker`,kind:`thing`,x:6,y:7,name:{nb:`Halvsirkelen av benker`,en:`The half-circle of benches`},look:`hotspot`,interactions:[{say:[{nb:`Benker i halvsirkel, så alle ser hverandre. Her sitter rådets sytti og øverstepresten.`,en:`Benches in a half-circle, so everyone can see everyone. Here sit the seventy and the high priest.`}],set:[`spor:benker`]}],area:`raadskammer`},{id:`nikodemus`,kind:`thing`,x:15,y:9,name:{nb:`Setet til Nikodemus`,en:`The seat of Nicodemus`},look:`hotspot`,interactions:[{say:[{nb:`En fariseer i rådet, som en gang spurte: dømmer loven vår noen uten å høre ham først? De avfeide ham. Ikke alle fariseere var motstandere.`,en:`A Pharisee in the council, who once asked if our law condemns a man unheard. They brushed him aside. Not all Pharisees were against him.`}],set:[`spor:nikodemus`]}],area:`raadskammer`},{id:`dor-ut-skriverkammer`,kind:`place`,x:15,y:17,name:{nb:`Ut i forgården`,en:`Out to the court`},look:`hotspot`,door:{area:`main`,x:21,y:5},area:`skriverkammer`},{id:`josefus`,kind:`thing`,x:16,y:9,name:{nb:`Josefus’ oversikt`,en:`Josephus’ overview`},look:`hotspot`,interactions:[{has:[],not:[],set:[`spor:josefus`],say:[{nb:`Et ark med det Josefus fortalte meg: «Jødene har tre retninger. Fariseerne tolker loven nøyaktig og tror at sjelen lever videre.`,en:`A sheet with what Josephus told me: “The Jews have three schools. The Pharisees read the law strictly and believe the soul lives on.`},{nb:`Saddukeerne avviser det og har bare de rike med seg. Essenerne lever i fellesskap og renhet.`,en:`The Sadducees reject that and have only the rich with them. The Essenes live in community and purity.`},{nb:`Og en fjerde retning, grunnlagt av Judas fra Galilea, er som fariseerne, men vil ikke kalle noe menneske herre.»`,en:`And a fourth, founded by Judas of Galilee, is like the Pharisees but will call no man lord.”`},{nb:`Under den har jeg notert det jeg hørte dem si i forgården. Hvem av de fire sier hva? Stemmer det, kan vitnene mine prøves mot ham.`,en:`Below it I have noted what I heard them say in the court. Which of the four says what? If it holds, my witnesses can be tested against him.`}],play:{game:`bins`,title:{nb:`Hvem sier hva?`,en:`Who says what?`},win:`retningene-sortert`,data:{bins:[{nb:`Fariseeren`,en:`The Pharisee`},{nb:`Saddukeeren`,en:`The Sadducee`},{nb:`Esseneren`,en:`The Essene`},{nb:`Den fjerde`,en:`The fourth`}],cards:[{text:{nb:`De døde skal stå opp, og englene finnes.`,en:`The dead will rise, and the angels exist.`},bin:0},{text:{nb:`Fedrenes overlevering veier like tungt som det skrevne.`,en:`The tradition of the fathers weighs as much as what is written.`},bin:0},{text:{nb:`Bare Moses’ bøker gjelder. Ingen oppstandelse.`,en:`Only the books of Moses count. No resurrection.`},bin:1},{text:{nb:`Templet er vårt, og vi sitter i Rådet.`,en:`The temple is ours, and we sit in the Council.`},bin:1},{text:{nb:`Vi lever i ørkenen, deler alt og venter på to salvede.`,en:`We live in the desert, share everything and wait for two anointed ones.`},bin:2},{text:{nb:`Vi teller dagene etter sola, ikke etter prestene i Jerusalem.`,en:`We count the days by the sun, not by the priests in Jerusalem.`},bin:2},{text:{nb:`Ingen herre uten Gud. Ikke keiseren!`,en:`No lord but God. Not the emperor!`},bin:3},{text:{nb:`Sverdet mot romerne, og det nå.`,en:`The sword against the Romans, and now.`},bin:3}],ask:{nb:`Hvem ville sagt dette?`,en:`Who would have said this?`}},key:!0}}],area:`skriverkammer`},{id:`notat`,kind:`thing`,x:13,y:9,name:{nb:`Lukas’ notat`,en:`Luke’s note`},look:`hotspot`,interactions:[{say:[{nb:`Et ark: «Saddukeerne må jeg forklare for Teofilos: de avviser oppstandelsen. Fariseerne trenger ingen forklaring; de er overalt.`,en:`A sheet: “The Sadducees I must explain to Theophilus: they deny the resurrection. The Pharisees need no explaining; they are everywhere.`},{nb:`Essenerne nevner vitnene mine aldri.»`,en:`The Essenes my witnesses never mention.”`}],set:[`spor:notat`]}],area:`skriverkammer`},{id:`moses`,kind:`thing`,x:26,y:10,name:{nb:`Moses’ bøker`,en:`The books of Moses`},look:`hotspot`,interactions:[{say:[{nb:`Fem ruller. Samaritanene godtar bare disse, og saddukeerne setter dem over alt annet. Fariseerne har også profetene, salmene og fedrenes tradisjon.`,en:`Five scrolls: all the Samaritans accept, and what the Sadducees put first. The Pharisees also have the prophets, the psalms and the tradition of the fathers.`}],set:[`spor:moses`]}],area:`skriverkammer`},{id:`daniel`,kind:`thing`,x:6,y:7,name:{nb:`Rullen med Daniel`,en:`The scroll of Daniel`},look:`hotspot`,interactions:[{say:[{nb:`Daniel: de som sover i jorda, skal våkne, noen til liv, noen til skam. Her finner fariseerne oppstandelsen; saddukeerne sier at Daniel ikke er Moses.`,en:`Daniel: those who sleep in the earth will awake, some to life, some to shame. Here the Pharisees find the resurrection; the Sadducees say Daniel is not Moses.`}],set:[`spor:daniel`]}],area:`skriverkammer`},{id:`soluret`,kind:`thing`,x:8,y:13,name:{nb:`Soluret`,en:`The sundial`},look:`hotspot`,interactions:[{say:[{nb:`Esseneren teller året etter sola: 364 dager, og hver høytid faller alltid på samme ukedag.`,en:`The Essene counts the year by the sun: 364 days, and every feast always falls on the same weekday.`}],set:[`spor:sol`]}]},{id:`maanetavla`,kind:`thing`,x:26,y:14,name:{nb:`Månetavla`,en:`The moon table`},look:`hotspot`,interactions:[{say:[{nb:`Prestene teller etter månen. Måneden begynner når nymånen ses fra muren.`,en:`The priests count by the moon. The month begins when the new moon is seen from the wall.`}],set:[`spor:maane`]}]},{id:`leke-fiken`,kind:`thing`,x:8,y:18,name:{nb:`Fikenboden`,en:`The fig stall`},look:`hotspot`,interactions:[{say:[{nb:`Fikenene triller. Esseneren går i en stor bue rundt dem. Tolleren plukker opp en og spiser den.`,en:`The figs roll away. The Essene walks a wide circle round them. The tax collector picks one up and eats it.`}],fx:`tip`}]},{id:`leke-skaal`,kind:`thing`,x:10,y:16,name:{nb:`Bronseskåla på boden`,en:`The bronze bowl on the stall`},look:`hotspot`,interactions:[{say:[{nb:`Klang! Saddukeeren ser strengt på deg. Den unge mannen ved porten flirer.`,en:`Clang! The Sadducee gives you a stern look. The young man by the gate grins.`}],fx:`ring`}]},{id:`leke-kar`,kind:`thing`,x:14,y:9,name:{nb:`Vaskekaret`,en:`The washing basin`},look:`hotspot`,interactions:[{say:[{nb:`Vannet skvulper. Fariseeren nikker fornøyd: endelig en som vasker hendene.`,en:`The water splashes. The Pharisee nods with approval: at last someone who washes their hands.`}],fx:`splash`}]},{id:`leke-glod`,kind:`thing`,x:17,y:9,name:{nb:`Glødefatet`,en:`The brazier`},look:`hotspot`,interactions:[{say:[{nb:`Glørne lyser opp. Grekeren varmer hendene på avstand. Lenger inn enn gjerdet får han ikke gå.`,en:`The embers glow. The Greek warms his hands from a distance. He may not go further in than the barrier.`}],fx:`light`}]},{id:`leke-duer`,kind:`thing`,x:11,y:14,name:{nb:`Duene`,en:`The doves`},look:`hotspot`,interactions:[{say:[{nb:`Duene flyr rett over gjerdet. De bryr seg ikke om hvem som får gå hvor.`,en:`The doves fly straight over the barrier. They don’t care who may go where.`}],fx:`scatter`}]}],facts:[{id:`fariseere`,title:{nb:`Fariseerne`,en:`The Pharisees`},body:{nb:`Kort sagt: Fariseerne tok loven på alvor i hverdagen og hadde folket med seg; evangeliene og Josefus er enige om det. Navnet betyr trolig «de atskilte». Josefus (Ant. 18,12–15; Krigen 2,162–163) sier de tolket loven nøyaktig, trodde på sjelens udødelighet og straff og lønn etter døden, og hadde folket med seg. De ville gjøre hele dagliglivet hellig gjennom «fedrenes tradisjon» (muntlig lov). Etter år 70 ble det deres arvtakere, rabbinerne, som formet jødedommen. Evangelienes bilde stemmer: lærere i synagogene, strenge på sabbat, tiende og renhet, tro på oppstandelsen (Apg 23,8). Men evangeliene er part i saken: de skarpe ordene (Luk 11,39–44) er sagt i strid, og Josefus, som selv hadde levd som fariseer, tegner dem mildere. Kildene er enige om læren og om innflytelsen hos folket, ikke om karakteren. Ikke alle var motstandere: Nikodemus (Joh 7,50–52), Gamaliel (Apg 5,34) og Paulus selv (Fil 3,5) var fariseere.`,en:`In short, the Pharisees took the law seriously in daily life and had the people with them; the Gospels and Josephus agree on that. The name probably means “the separated ones”. Josephus (Ant. 18.12–15; War 2.162–163) says they interpreted the law exactly, believed in the immortality of the soul and reward and punishment after death, and had the people with them. They wanted to make all of daily life holy through “the tradition of the fathers” (oral law). After AD 70 it was their heirs, the rabbis, who shaped Judaism. The Gospels’ picture fits: teachers in the synagogues, strict on sabbath, tithe and purity, belief in the resurrection (Acts 23:8). But the Gospels are a party to the dispute: the sharp words (Luke 11:39–44) are spoken in conflict, and Josephus, who had himself lived as a Pharisee, paints them more mildly. The sources agree on the teaching and the influence with the people, not on the character. Not all were opponents: Nicodemus (John 7:50–52), Gamaliel (Acts 5:34) and Paul himself (Phil 3:5) were Pharisees.`},unlockedBy:`fakta:fariseere`},{id:`saddukeere`,title:{nb:`Saddukeerne`,en:`The Sadducees`},body:{nb:`Trolig oppkalt etter Sadok, Davids prest. Josefus (Ant. 18,16–17) sier de bare hadde de rike med seg, avviste sjelens liv etter døden, og at folket ikke ville høre på dem. De sto nær templet og øversteprestene (Apg 5,17) og holdt fred med Roma. Lukas forklarer for leseren at de «sier at det ikke er noen oppstandelse» (Luk 20,27; Apg 23,8), slik man gjør for en som ikke kjenner landet. De forsvant med templet i år 70. Senere kirkefedre sa at de bare godtok Mosebøkene; Josefus sier bare at de avviste den muntlige tradisjonen. Alle kildene våre om saddukeerne (Josefus, Det nye testamente, rabbinerne) er skrevet av motstandere; ingen saddukeisk tekst er bevart.`,en:`Probably named after Zadok, David’s priest. Josephus (Ant. 18.16–17) says they had only the rich with them, denied the soul’s life after death, and that the people would not listen to them. They stood close to the temple and the high priests (Acts 5:17) and kept peace with Rome. Luke explains to the reader that they “say there is no resurrection” (Luke 20:27; Acts 23:8), as one does for someone who does not know the land. They disappeared with the temple in AD 70. Later church fathers said they accepted only the books of Moses; Josephus says only that they rejected the oral tradition. All our sources on the Sadducees (Josephus, the New Testament, the rabbis) were written by opponents; no Sadducean text survives.`},unlockedBy:`fakta:saddukeere`},{id:`essenere`,title:{nb:`Essenerne`,en:`The Essenes`},body:{nb:`Josefus (Krigen 2,119–161), Filon og Plinius beskriver essenerne: felles eiendom, daglige renselsesbad, måltider i stillhet, strenge sabbatsregler, noen ugifte. De fleste forskere knytter dem til samfunnet ved Qumran, der Dødehavsrullene ble funnet fra 1947. Rullene viser forventning om to messiaser (prest og konge), en annen kalender enn templets, og at vanføre var utelukket fra forsamlingen (1QSa 2,5–9). Evangeliene nevner aldri essenerne; forklaringen kan være at de holdt seg for seg selv, og at Jesus ikke møtte dem. Fraværet er et lite tegn på at evangelistene ikke konstruerte motstandere. Navnet «essener» er gresk; rullene kaller seg «yahad», fellesskapet. Krigsrullen fra Qumran (1QM) beskriver en endetidskrig mellom «lysets sønner» og «mørkets sønner». Josefus sier at essenerne bodde spredt i mange byer (Krigen 2,124), ikke bare ved Dødehavet.`,en:`Josephus (War 2.119–161), Philo and Pliny describe the Essenes: common property, daily washings, meals in silence, strict sabbath rules, some unmarried. Most scholars link them to the community at Qumran, where the Dead Sea Scrolls were found from 1947 onwards. The scrolls show an expectation of two Messiahs (priest and king), a different calendar from the temple’s, and that the disabled were excluded from the assembly (1QSa 2:5–9). The Gospels never mention the Essenes; the explanation may be that they kept to themselves, and that Jesus did not meet them. The absence is a small sign that the evangelists did not construct opponents. The name “Essene” is Greek; the community in the scrolls calls itself “yahad”, the community. The War Scroll from Qumran (1QM) describes an end-time war between “the sons of light” and “the sons of darkness”. Josephus says the Essenes lived scattered in many towns (War 2.124), not only by the Dead Sea.`},unlockedBy:`fakta:essenere`},{id:`fjerde`,title:{nb:`Den fjerde retningen`,en:`The fourth school`},body:{nb:`Josefus (Ant. 18,23) kaller Judas fra Galileas tilhengere «den fjerde filosofien»: som fariseerne i lære, men med en «ubøyelig kjærlighet til friheten» og Gud som eneste herre. Ordet «selot» (ivrer) om et organisert parti bruker Josefus først om opprøret fra år 66; at Simon kalles «seloten» blant de tolv (Luk 6,15), betyr trolig «den ivrige». Spørsmålet om skatt til keiseren (Luk 20,20–26) var nettopp dette partiets prøvestein, og Jesu svar ville ha skuffet dem. Josefus’ inndeling i «filosofier» er laget for greske lesere, som kjente stoikere og epikureere. De fleste jøder hørte ikke til noen av dem, og «den fjerde» er Josefus’ egen merkelapp på dem han ville gi skylden for krigen i 66. Judas fra Galilea gjorde opprør da romerne lot folket i Judea telle og skattlegge i år 6 (Apg 5,37; Josefus, Ant. 18,1–10).`,en:`Josephus (Ant. 18.23) calls the followers of Judas of Galilee “the fourth philosophy”: like the Pharisees in doctrine, but with an “inviolable love of freedom” and God as the only lord. Josephus first uses the word “Zealot” for an organised party in connection with the revolt of AD 66; that Simon is called “the Zealot” among the twelve (Luke 6:15) probably means “the zealous one”. The question of tax to the emperor (Luke 20:20–26) was exactly this party’s touchstone, and Jesus’ answer would have disappointed them. Josephus’ division into “philosophies” is made for Greek readers, who knew Stoics and Epicureans. Most Jews belonged to none of them, and “the fourth” is Josephus’ own label for those he wanted to blame for the war of 66. Judas of Galilee rebelled when the Romans had the people of Judea counted and taxed in AD 6 (Acts 5:37; Josephus, Ant. 18.1–10).`},unlockedBy:`fakta:fjerde`},{id:`samaritanere`,title:{nb:`Samaritanene`,en:`The Samaritans`},body:{nb:`Samaritanene regnet seg som Israels rest i nord, med sitt eget tempel på Garisim (ødelagt av Johannes Hyrkanos ca. 110 f.Kr.) og bare Mosebøkene som Skrift. Jødene så dem som fremmede med blandet opphav (2 Kong 17). Fiendskapet var skarpt: Josefus forteller om samaritaner som spredte knokler i templet, og om drap på galileiske pilegrimer (Ant. 18,30; 20,118). Lukas har tre samaritanfortellinger som ingen andre har: landsbyen som avviste ham (9,51–56), den barmhjertige samaritan (10,25–37) og den spedalske som vendte tilbake (17,11–19). Et lite samaritansk samfunn finnes ennå ved Garisim. Noen jøder gikk omveier for å slippe Samaria, men Josefus sier at galileere pleide å gå gjennom landet på vei til høytidene (Ant. 20,118).`,en:`The Samaritans counted themselves as Israel’s remnant in the north, with their own temple on Gerizim (destroyed by John Hyrcanus c. 110 BC) and only the books of Moses as Scripture. The Jews saw them as foreigners of mixed origin (2 Kgs 17). The enmity was sharp: Josephus tells of Samaritans who scattered bones in the temple, and of killings of Galilean pilgrims (Ant. 18.30; 20.118). Luke has three Samaritan stories no one else has: the village that rejected him (9:51–56), the good Samaritan (10:25–37) and the leper who returned (17:11–19). A small Samaritan community still exists by Gerizim. Some Jews took detours to avoid Samaria, but Josephus says Galileans usually went through the land on their way to the feasts (Ant. 20.118).`},unlockedBy:`fakta:samaritanere`},{id:`gudfryktige`,title:{nb:`De gudfryktige og gjerdet`,en:`The God-fearers and the barrier`},body:{nb:`Hedninger som trodde på Israels Gud uten å bli omskåret, kalles «gudfryktige» i Apostlenes gjerninger (10,2; 13,16; 17,4); en innskrift fra Afrodisias (trolig 300-tallet eller senere; dateringen er omstridt) lister dem som egen gruppe ved synagogen. I templet stoppet de ved soreg, en lav mur med tavler på gresk og latin som truet enhver fremmed som gikk forbi med døden; to slike tavler er funnet (1871 og 1935). Josefus bekrefter at romerne lot jødene håndheve dette, selv mot romerske borgere (Krigen 6,124–126). Opptøyene mot Paulus (Apg 21,28–29) handlet om nettopp denne muren. Lukas forteller også om en romersk offiser i Kapernaum som hadde bygd synagogen der (Luk 7,1–10).`,en:`Gentiles who believed in the God of Israel without being circumcised are called “God-fearers” in Acts (10:2; 13:16; 17:4); an inscription from Aphrodisias (probably from the fourth century or later; the dating is disputed) lists them as a separate group at the synagogue. In the temple they stopped at the soreg, a low wall with plaques in Greek and Latin threatening with death any foreigner who passed; two such plaques have been found (1871 and 1935). Josephus confirms that the Romans let the Jews enforce this, even against Roman citizens (War 6.124–126). The riot against Paul (Acts 21:28–29) was about precisely this wall. Luke also tells of a Roman officer in Capernaum who had built the synagogue there (Luke 7:1–10).`},unlockedBy:`fakta:gudfryktige`},{id:`svaret-fra-tornebusken`,title:{nb:`Svaret fra tornebusken`,en:`The answer from the burning bush`},body:{nb:`Saddukeerne godtok ikke oppstandelsen og la mest vekt på Mosebøkene. Jesus svarer dem derfor fra 2 Mos 3,6, der Gud kaller seg Abrahams, Isaks og Jakobs Gud lenge etter at de var døde: han er de levendes Gud (Luk 20,27–38). Lukas tar med at noen av de skriftlærde sa «godt svart, Mester» (Luk 20,39), en av de få gangene motstandere gir ham rett, og han lar det stå.`,en:`The Sadducees did not accept the resurrection and put most weight on the books of Moses. So Jesus answers them from Exod 3:6, where God calls himself the God of Abraham, Isaac and Jacob long after they had died: he is the God of the living (Luke 20:27–38). Luke includes that some of the scribes said “well answered, Teacher” (Luke 20:39), one of the few times opponents agree with him, and he lets it stand.`},unlockedBy:`oppstandelsen-lost`},{id:`diktet`,title:{nb:`Hva er funnet på i denne episoden?`,en:`What is made up in this episode?`},body:{nb:`Alle du møter i forgården og i rådskammeret, er funnet på, og det samme er det de sier. At Lukas snakket med Josefus, er også funnet på; vi vet ikke om de to noen gang møttes. Josefus skrev om de fire retningene mange år senere: i Den jødiske krigen (bok 2, omkring år 75) og i Jødiske antikviteter (bok 18, omkring år 93). Det spillet prøver, er om bildet hos Lukas stemmer med bildet hos Josefus. Setet til Nikodemus og benkene i rådskammeret er også laget for spillet.`,en:`Everyone you meet in the forecourt and in the council chamber is made up, and so is what they say. That Luke talked with Josephus is made up too; we do not know whether the two ever met. Josephus wrote about the four schools many years later: in the Jewish War (book 2, around AD 75) and in the Jewish Antiquities (book 18, around AD 93). What the game tests is whether Luke’s picture matches the one in Josephus. Nicodemus’ seat and the benches in the council chamber are also made for the game.`},unlockedBy:`mot-josefus-lost`}],clues:[{id:`fariseer`,source:{nb:`Fariseeren`,en:`The Pharisee`},text:{nb:`De atskilte: loven med gjerder rundt, hele folket hellig ved hvert bord. Tror på oppstandelse, engler og dom. Folket hører på dem.`,en:`The separated ones: the law with fences around it, the whole people holy at every table. Believe in resurrection, angels and judgement. The people listen to them.`},unlockedBy:`spor:fariseer`},{id:`fariseer-jesus`,source:{nb:`Fariseeren`,en:`The Pharisee`},text:{nb:`Jesus spiste hos fariseere og hos tollere, og sa de vasket utsiden av begeret. Noen fulgte ham likevel.`,en:`Jesus ate with Pharisees and with tax collectors, and said they washed the outside of the cup. Some followed him all the same.`},unlockedBy:`spor:fariseer-jesus`},{id:`saddukeer`,source:{nb:`Saddukeeren`,en:`The Sadducee`},text:{nb:`Prestefamiliene; templet er deres. Moses’ fem bøker over alt annet. Ingen oppstandelse, ingen engler. Fred med Roma.`,en:`The priestly families; the temple is theirs. The five books of Moses above everything else. No resurrection, no angels. Peace with Rome.`},unlockedBy:`spor:saddukeer`},{id:`gaaten`,source:{nb:`Saddukeeren`,en:`The Sadducee`},text:{nb:`Gåten om sju brødre og én kone. Jesus svarte fra tornebusken: Abrahams Gud er ikke de dødes Gud. De hadde ikke noe svar.`,en:`The riddle about seven brothers and one wife. Jesus answered from the burning bush: the God of Abraham is not the God of the dead. They had no answer.`},unlockedBy:`spor:gaaten`},{id:`essener`,source:{nb:`Esseneren`,en:`The Essene`},text:{nb:`Har forlatt templet; bor sammen, deler alt, renser seg daglig. Venter på to salvede. Spedalske og lamme får ikke sitte til bords.`,en:`Have left the temple; live together, share everything, wash daily. Wait for two anointed ones. Lepers and the lame may not sit at table.`},unlockedBy:`spor:essener`},{id:`essener-jesus`,source:{nb:`Esseneren`,en:`The Essene`},text:{nb:`Jesus rørte ved spedalske og kalte lamme og blinde til bords. Det motsatte av essenerne.`,en:`Jesus touched lepers and called the lame and the blind to the table. The opposite of the Essenes.`},unlockedBy:`spor:essener-jesus`},{id:`ung`,source:{nb:`Den unge ved porten`,en:`The young man at the gate`},text:{nb:`Ingen herre uten Gud; skatt til keiseren er å kalle ham herre. Venter på dagen de tar sverdet.`,en:`No lord but God; tax to the emperor is calling him lord. Waiting for the day they take the sword.`},unlockedBy:`spor:ung`},{id:`skatten`,source:{nb:`Den unge ved porten`,en:`The young man at the gate`},text:{nb:`De spurte Jesus om skatten. Han så på keiserens bilde på mynten: gi keiseren det som er keiserens, og Gud det som er Guds.`,en:`They asked Jesus about the tax. He looked at the emperor’s image on the coin: give the emperor what is the emperor’s, and God what is God’s.`},unlockedBy:`spor:skatten`},{id:`toller`,source:{nb:`Tolleren`,en:`The tax collector`},text:{nb:`Hører ikke til noen av dem. Jesus kalte Levi og spiste med tollerne: de syke trenger lege.`,en:`Belongs to none of them. Jesus called Levi and ate with the tax collectors: the sick need a doctor.`},unlockedBy:`spor:toller`},{id:`samaritan`,source:{nb:`Samaritanen`,en:`The Samaritan`},text:{nb:`Garisim, bare Moses’ bøker, kalt fremmede. Jesus gikk gjennom landet deres, nektet å kalle ild ned, og gjorde en samaritan til den gode i en historie.`,en:`Gerizim, only the books of Moses, called foreigners. Jesus walked through their land, refused to call down fire, and made a Samaritan the good one in a story.`},unlockedBy:`spor:samaritan`},{id:`greker`,source:{nb:`Den gudfryktige grekeren`,en:`The God-fearing Greek`},text:{nb:`Tror på Israels Gud, men er ikke omskåret og stopper ved gjerdet. Vil vite om det er plass for slike som ham.`,en:`Believes in the God of Israel, but is not circumcised and stops at the barrier. Wants to know if there is room for people like him.`},unlockedBy:`spor:greker`},{id:`gjerdet`,source:{nb:`Det du selv så`,en:`What you saw yourself`},text:{nb:`Innskriften på gresk og latin: ingen fremmed innenfor, ellers venter døden.`,en:`The inscription in Greek and Latin: no foreigner inside, on pain of death.`},unlockedBy:`spor:gjerdet`},{id:`josefus`,source:{nb:`Josefus’ oversikt`,en:`Josephus’ overview`},text:{nb:`Tre retninger: fariseere (loven nøyaktig, sjelen lever), saddukeere (avviser det, bare de rike), essenere (fellesskap og renhet). Og en fjerde fra Judas fra Galilea: ingen herre uten Gud.`,en:`Three schools: Pharisees (the law exactly, the soul lives), Sadducees (reject that, only the rich), Essenes (community and purity). And a fourth from Judas of Galilee: no lord but God.`},unlockedBy:`retningene-sortert`},{id:`notat`,source:{nb:`Lukas’ notat`,en:`Luke’s note`},text:{nb:`Saddukeerne må forklares for Teofilos; fariseerne ikke. Essenerne nevner vitnene aldri.`,en:`The Sadducees must be explained to Theophilus; the Pharisees do not need to be. The Essenes the witnesses never mention.`},unlockedBy:`spor:notat`},{id:`moses`,source:{nb:`Moses’ bøker`,en:`The books of Moses`},text:{nb:`Samaritanene godtar bare de fem bøkene; saddukeerne setter dem over alt annet; fariseerne har profetene, salmene og tradisjonen i tillegg.`,en:`The Samaritans accept only the five books; the Sadducees set them above everything else; the Pharisees have the prophets, the psalms and the tradition as well.`},unlockedBy:`spor:moses`},{id:`daniel`,source:{nb:`Rullen med Daniel`,en:`The scroll of Daniel`},text:{nb:`De som sover i jorda, skal stå opp. Her finner fariseerne oppstandelsen; saddukeerne sier Daniel ikke er Moses.`,en:`Those who sleep in the earth will rise. Here the Pharisees find the resurrection; the Sadducees say Daniel is not Moses.`},unlockedBy:`spor:daniel`},{id:`benker`,source:{nb:`Det du selv så`,en:`What you saw yourself`},text:{nb:`Benker i halvsirkel så alle ser hverandre; rådets sytti og øverstepresten.`,en:`Benches in a half-circle so that everyone can see everyone else; the council’s seventy and the high priest.`},unlockedBy:`spor:benker`},{id:`raadsherre`,source:{nb:`Rådsherren`,en:`The councillor`},text:{nb:`Sanhedrin: øverstepresten, saddukeere og fariseere, sjelden enige. Paulus splittet dem med ordet «oppstandelsen».`,en:`The Sanhedrin: the high priest, Sadducees and Pharisees, seldom in agreement. Paul split them with the word “resurrection”.`},unlockedBy:`spor:raadsherre`},{id:`raadet`,source:{nb:`Rådsherren`,en:`The councillor`},text:{nb:`Morgenen de dømte Jesus, sto øversteprestene, de eldste og de skriftlærde samlet; prestene fryktet for templet og Roma. Josef fra Arimatea var ikke med på dommen.`,en:`The morning they condemned Jesus, the chief priests, the elders and the scribes stood together; the priests feared for the temple and Rome. Joseph of Arimathea did not consent to the verdict.`},unlockedBy:`spor:raadet`},{id:`nikodemus`,source:{nb:`Setet til Nikodemus`,en:`The seat of Nicodemus`},text:{nb:`En fariseer i rådet som ba dem høre ham først. Ikke alle fariseere var motstandere.`,en:`A Pharisee in the council who asked them to hear him first. Not all Pharisees were opponents.`},unlockedBy:`spor:nikodemus`}],deductions:[{id:`fire`,question:{nb:`Hvem er de fire flokkene, og hva skiller dem?`,en:`Who are the four groups, and what separates them?`},clues:[`fariseer`,`saddukeer`,`essener`,`ung`],steps:[{ask:{nb:`Hva sa fariseeren og saddukeeren om seg selv?`,en:`What did the Pharisee and the Sadducee say about themselves?`},clues:[`fariseer`,`saddukeer`],yes:{nb:`Folket og loven mot templet og Moses. Og esseneren og den unge?`,en:`The people and the law against the temple and Moses. And the other two?`},no:{nb:`Ikke den lappen. Jeg spør hva fariseeren og saddukeeren sa om seg selv.`,en:`Not that note. I am asking what the Pharisee and the Sadducee said about themselves.`}},{ask:{nb:`Hva sa esseneren og den unge om seg selv?`,en:`What did the Essene and the young man say about themselves?`},clues:[`essener`,`ung`],yes:{nb:`Renhet og sverd. Hva skiller dem?`,en:`Purity and the sword. What separates them?`},no:{nb:`Ikke den lappen. Jeg spør hva esseneren og den unge sa om seg selv.`,en:`Not that note. I am asking what the Essene and the young man said about themselves.`}}],options:[{text:{nb:`Fariseere: loven og oppstandelsen. Saddukeere: templet og Roma. Essenere: renhet. Den fjerde: bare Gud`,en:`Pharisees: the law and the resurrection. Sadducees: the temple and Rome. Essenes: purity. The fourth: God alone`},feedback:{nb:`Riktig. De er uenige om nesten alt: hva som er Skrift, om det finnes en oppstandelse, hvem som er ren, og hva man skal gjøre med Roma.`,en:`Correct. They disagree about nearly everything: what is Scripture, whether there is a resurrection, who is clean, and what to do about Rome.`},correct:!0},{text:{nb:`Fire navn på det samme; alle trodde likt om loven, templet og Roma`,en:`Four names for one thing; all believed alike on law, temple and Rome`},feedback:{nb:`Nei. Hør saddukeeren og fariseeren om oppstandelsen, og esseneren om templet. De står stikk mot hverandre.`,en:`No. Listen to the Sadducee and the Pharisee on the resurrection, and the Essene on the temple. They are flatly opposed to each other.`}},{text:{nb:`Fire slags prester i templet, som delte tjenesten mellom seg etter hvilken slekt de kom fra, og ellers trodde det samme`,en:`Four kinds of priests in the temple, who shared the service between them according to which family they came from, and otherwise believed the same`},feedback:{nb:`Nei. Bare saddukeerne hører til prestefamiliene i templet. Esseneren har forlatt templet, fariseeren sitter i synagogen, og den unge vil ha sverd.`,en:`No. Only the Sadducees belong to the priestly families of the temple. The Essene has left the temple, the Pharisee sits in the synagogue, and the young man wants a sword.`}}],set:[`fire-lost`]},{id:`oppstandelsen`,question:{nb:`Hvorfor krangler de om oppstandelsen, og hva svarte Jesus?`,en:`Why do they quarrel about the resurrection, and what did Jesus answer?`},clues:[`moses`,`daniel`,`gaaten`],steps:[{ask:{nb:`Finn Moses’ bøker og rullen med Daniel.`,en:`Find the books of Moses and the scroll of Daniel.`},clues:[`moses`,`daniel`],yes:{nb:`Moses for saddukeerne, Daniel for fariseerne. Hva sa saddukeeren om gåten?`,en:`Moses for the Sadducees, Daniel for the Pharisees. And the riddle?`},no:{nb:`Det er ikke rullene.`,en:`Those are not the scrolls.`}},{ask:{nb:`Hva sa saddukeeren om gåten med sju brødre?`,en:`What did the Sadducee say about the riddle with seven brothers?`},clues:[`gaaten`],yes:{nb:`Han svarte fra Moses selv. Hvorfor var det et godt svar?`,en:`He answered from Moses himself. Why was that a good answer?`},no:{nb:`Det er ikke gåten.`,en:`That is not the riddle.`}}],options:[{text:{nb:`Striden gjelder hva som er Skrift; Jesus svarte saddukeerne fra Moses selv`,en:`The dispute is over what is Scripture; Jesus answered the Sadducees from Moses`},feedback:{nb:`Riktig. Han svarte fra Moses, der saddukeerne selv sto. Gud kaller seg Abrahams Gud lenge etter at Abraham døde; altså lever Abraham for Gud.`,en:`Correct. He answered from Moses, where the Sadducees themselves stood. God calls himself Abraham’s God long after Abraham died; so Abraham lives for God.`},correct:!0},{text:{nb:`Jesus sa at saddukeerne hadde rett: siden det ikke står hos Moses, finnes det ingen oppstandelse`,en:`Jesus said the Sadducees were right: since it is not written in Moses, there can be no resurrection`},feedback:{nb:`Nei. Han sa de tok feil, fordi de ikke kjente Skriftene eller Guds kraft. Og han viste det fra Moses.`,en:`No. He said they were wrong, because they knew neither the Scriptures nor God’s power. And he showed it from Moses.`}},{text:{nb:`Jesus svarte fra Daniel, og saddukeerne måtte gi seg`,en:`Jesus answered from Daniel, and the Sadducees gave in`},feedback:{nb:`Nei. Det hadde veid lite; for saddukeerne er det Moses som gjelder, og det var fra Moses de selv hadde spurt. Han gikk til Moses.`,en:`No. That would have weighed little; for the Sadducees it is Moses that counts, and it was from Moses they themselves had asked. He went to Moses.`}}],set:[`oppstandelsen-lost`]},{id:`de-andre`,question:{nb:`Hvem står utenfor alle fire flokkene, og hvordan møtte Jesus dem?`,en:`Who stands outside all four groups, and how did Jesus meet them?`},clues:[`toller`,`samaritan`,`greker`,`gjerdet`],steps:[{ask:{nb:`Hva sa tolleren og samaritanen?`,en:`What did the tax collector and the Samaritan say?`},clues:[`toller`,`samaritan`],yes:{nb:`Ingen vil ha dem, men han gikk til dem. Og grekeren?`,en:`Nobody wants them, but he went to them. And the Greek?`},no:{nb:`Det er ikke tolleren eller samaritanen.`,en:`That is not the tax collector or the Samaritan.`}},{ask:{nb:`Hva sa grekeren, og hva så du på gjerdet?`,en:`What did the Greek say, and what did you see on the barrier?`},clues:[`greker`,`gjerdet`],yes:{nb:`Han spør om det er plass. Hva er svaret?`,en:`He asks if there is room. What is the answer?`},no:{nb:`Det er ikke grekeren eller gjerdet.`,en:`That is not the Greek or the barrier.`}}],options:[{text:{nb:`Tollere, samaritaner og hedninger. Jesus spiste med tollere og hedret en samaritan`,en:`Tax collectors, Samaritans, gentiles. Jesus ate with tax collectors and honoured a Samaritan`},feedback:{nb:`Riktig. Det er slike jeg skriver for, og Teofilos er kanskje en av dem. Ingen av de fire ville valgt en toller og en samaritan som vitner.`,en:`Correct. I write for such people, Theophilus perhaps among them. None of the four would have picked a tax collector and a Samaritan as witnesses.`},correct:!0},{text:{nb:`Jesus holdt seg unna dem, som alle andre, for ikke å bli uren og miste folket som fulgte ham`,en:`Jesus kept away from them, like everyone else, so as not to become unclean and lose the people who followed him`},feedback:{nb:`Nei. Levi, samaritanlandsbyen, offiseren i Kapernaum. Han gikk dit de andre ikke gikk, og fariseerne spurte hvorfor.`,en:`No. Levi, the Samaritan village, the officer in Capernaum. He went where the others did not, and the Pharisees asked why.`}},{text:{nb:`Det fantes ingen utenfor flokkene; hver jøde hørte til én av de fire, og hedningene telte ikke`,en:`There was nobody outside the groups; every Jew belonged to one of the four, and the gentiles did not count`},feedback:{nb:`Jo. De fleste i landet hørte ikke til noen flokk. Og tollerne, samaritanene og hedningene ble holdt utenfor med vilje; grekeren stopper ved gjerdet.`,en:`There were. Most in the land belonged to no group. And the tax collectors, Samaritans and gentiles were kept out on purpose; the Greek stops at the barrier.`}}],set:[`de-andre-lost`]},{id:`mot-josefus`,question:{nb:`Stemmer det Lukas’ vitner forteller, med det Josefus forteller?`,en:`Does what Luke’s witnesses say fit what Josephus says?`},clues:[`josefus`,`notat`,`raadsherre`],steps:[{ask:{nb:`Finn Josefus’ oversikt og notatet mitt.`,en:`Find Josephus’ overview and my note.`},clues:[`josefus`,`notat`],yes:{nb:`Hos meg nevnes essenerne aldri. Hva sa rådsherren?`,en:`My account never mentions the Essenes. And the council?`},no:{nb:`Det er ikke oversikten eller notatet.`,en:`That is not the overview or the note.`}},{ask:{nb:`Hva sa rådsherren om Paulus og ordet «oppstandelsen»?`,en:`What did the councillor say about Paul and the word “resurrection”?`},clues:[`raadsherre`],yes:{nb:`Saddukeere og fariseere, splittet på ordet oppstandelsen. Stemmer det?`,en:`Sadducees and Pharisees, split on the word resurrection. Does it fit?`},no:{nb:`Ikke den lappen. Jeg spør hva rådsherren sa om Paulus og ordet «oppstandelsen».`,en:`Not that note. I am asking what the councillor said about Paul and the word “resurrection”.`}}],options:[{text:{nb:`Ja, i det store: de samme fariseerne og saddukeerne, og samme strid om oppstandelsen`,en:`Yes, in the main: the same Pharisees and Sadducees, and the same dispute over the resurrection`},feedback:{nb:`Riktig. Samme partier, samme strid, og essenerne holdt seg for seg selv. Hadde jeg diktet dette langt herfra, hadde jeg neppe truffet så godt.`,en:`Correct. The same parties, the same quarrel, the Essenes apart. Had I made this up far from here, I would hardly have got it so right.`},correct:!0},{text:{nb:`Nei, Josefus kjenner ikke fariseerne; han vet bare hva saddukeerne mener`,en:`No, Josephus does not know the Pharisees; he knows only the Sadducees`},feedback:{nb:`Jo. Han prøvde alle tre, sier han, og endte hos fariseerne. Han kjenner dem innenfra.`,en:`He does. He tried all three, he says, and ended up with the Pharisees. He knows them from the inside.`}},{text:{nb:`Lukas har skrevet av Josefus, og derfor stemmer det; det er samme kilde to ganger`,en:`Luke has copied Josephus, and that is why it fits; it is the same source twice over`},feedback:{nb:`Nei. Josefus har ikke skrevet noe ennå; han er en ung prest som forteller meg det han selv har sett. At det han sier, stemmer med det vitnene mine forteller, er noe annet enn avskrift.`,en:`No. Josephus has written nothing yet; he is a young priest telling me what he has seen himself. That what he says fits what my witnesses say is something other than copying.`}}],set:[`mot-josefus-lost`]},{id:`passet-ikke`,question:{nb:`Hvilken flokk hørte Jesus til?`,en:`Which group did Jesus belong to?`},clues:[`fariseer-jesus`,`essener-jesus`,`skatten`,`gaaten`],steps:[{ask:{nb:`Hva sa fariseeren og esseneren om Jesus?`,en:`What did the Pharisee and the Essene say about Jesus?`},clues:[`fariseer-jesus`,`essener-jesus`],yes:{nb:`Tollere og spedalske. Og den unge og saddukeeren?`,en:`Tax collectors and lepers. And the other two?`},no:{nb:`Det er ikke det fariseeren og esseneren sa om Jesus.`,en:`That is not what the Pharisee and the Essene said about Jesus.`}},{ask:{nb:`Hva sa den unge om skatten, og saddukeeren om gåten?`,en:`What did the young man say about the tax, and the Sadducee about the riddle?`},clues:[`skatten`,`gaaten`],yes:{nb:`Gi keiseren det som er keiserens; og Abrahams Gud er de levendes Gud. Hvilken flokk?`,en:`The emperor’s coin, and the God of the living. Which group?`},no:{nb:`Det er ikke skatten eller gåten.`,en:`That is not the tax or the riddle.`}}],options:[{text:{nb:`Ingen. Han sto imot hver av dem på et punkt: oppstandelse, renhet, keiseren`,en:`None. He stood against each of them on some point: resurrection, purity, the emperor`},feedback:{nb:`Riktig. Alle fire kunne ha laget en Messias etter seg selv; ingen av dem laget denne. Det er én av grunnene til at jeg stoler på vitnene.`,en:`Correct. All four could have made a Messiah in their own image; none of them made this one. That is one reason I trust the witnesses.`},correct:!0},{text:{nb:`Fariseerne, for han trodde på oppstandelsen, på engler og på dommen, slik de gjør`,en:`The Pharisees, for he believed in the resurrection, in angels and in the judgement, as they do`},feedback:{nb:`Nei. Der var han enig med dem, ja, men han spiste med tollere og sa at de vasket utsiden av begeret. Ikke en fariseer.`,en:`No. There he agreed with them, yes, but he ate with tax collectors and said they washed the outside of the cup. Not a Pharisee.`}},{text:{nb:`Den fjerde flokken, for romerne korsfestet ham som opprører, og det gjør de bare med dem`,en:`The fourth group, for the Romans crucified him as a rebel, and they do that only to such men`},feedback:{nb:`Nei. Gi keiseren det som er keiserens, sa han. Den unge ved porten forstår det ennå ikke, og romerne tok feil av ham.`,en:`No. Give the emperor what is the emperor’s, he said. The young man at the gate still does not understand it, and the Romans misjudged him.`}}],set:[`passet-ikke-lost`]},{id:`raadet`,question:{nb:`Hvem satt i det store rådet, og hvorfor betyr det noe?`,en:`Who sat in the great council, and why does it matter?`},clues:[`raadsherre`,`raadet`,`nikodemus`,`benker`],steps:[{ask:{nb:`Finn rådsherren, benkene og setet til Nikodemus.`,en:`Find the councillor, the benches and Nicodemus’ seat.`},clues:[`raadsherre`,`raadet`,`nikodemus`,`benker`],yes:{nb:`Øversteprest, saddukeere, fariseere; sjelden enige; én som ba dem høre først. Sett det sammen.`,en:`High priest, Sadducees, Pharisees; seldom in agreement; one who asked them to hear first. Put it together.`},no:{nb:`Det handler ikke om rådet.`,en:`That is not about the council.`}}],set:[`raadet-lost`],options:[{text:{nb:`Saddukeiske prester førte an, fariseerne satt der og var delt, og ikke alle var med på dommen`,en:`Sadducee priests led, the Pharisees sat there divided, and not all agreed to the verdict`},feedback:{nb:`Riktig. To partier som sjelden tålte hverandre, og en sak der prestene førte an mens fariseerne var delt.`,en:`Correct. Two parties that could rarely stand each other, and a case where the priests led while the Pharisees were divided.`},correct:!0},{text:{nb:`Bare saddukeere; fariseerne hadde ikke plass i rådet, de satt i synagogene og hadde folket, men ikke makten`,en:`Only Sadducees; the Pharisees had no seat in the council, they sat in the synagogues and had the people, but not the power`},feedback:{nb:`Nei. Rådsherren og Nikodemus’ sete sier noe annet: fariseere satt der.`,en:`No. The councillor and Nicodemus’ seat say otherwise: Pharisees sat there.`}},{text:{nb:`Bare fariseere, for det var dem folket hørte på`,en:`Only Pharisees, for they were the ones the people heard`},feedback:{nb:`Nei. Øverstepresten var saddukeer, og prestene førte an.`,en:`No. The high priest was a Sadducee, and the priests led the way.`}}]}],objectives:[{text:{nb:`Snakk med Lukas`,en:`Talk to Luke`},doneBy:[`oppdrag`]},{text:{nb:`Snakk med fariseeren, saddukeeren, esseneren og den unge`,en:`Talk to the Pharisee, the Sadducee, the Essene and the young man`},doneBy:[`spor:fariseer`,`spor:saddukeer`,`spor:essener`,`spor:ung`]},{text:{nb:`Snakk med tolleren, samaritanen og grekeren, og se på gjerdet`,en:`Talk to the tax collector, the Samaritan and the Greek, and look at the barrier`},doneBy:[`spor:toller`,`spor:samaritan`,`spor:greker`,`spor:gjerdet`]},{text:{nb:`Gå inn i rådskammeret`,en:`Go into the council chamber`},doneBy:[`spor:raadsherre`,`spor:benker`,`spor:nikodemus`]},{text:{nb:`Les arkene og rullene i skriverkammeret, og sorter hvem som sier hva`,en:`Read the sheets and scrolls in the scribe’s chamber, and sort who says what`},doneBy:[`spor:josefus`,`spor:notat`,`spor:moses`,`spor:daniel`,`retningene-sortert`]},{text:{nb:`Løs sakene i vitneboka`,en:`Solve the cases in the notebook`},doneBy:[`fire-lost`,`oppstandelsen-lost`,`de-andre-lost`,`mot-josefus-lost`,`passet-ikke-lost`,`raadet-lost`]},{text:{nb:`Gå tilbake til Lukas`,en:`Go back to Luke`},doneBy:[`avsluttet`]}],rewards:[{flag:`fire-lost`,points:15,label:{nb:`Skill de fire flokkene`,en:`Tell the four groups apart`}},{flag:`oppstandelsen-lost`,points:15,label:{nb:`Forstå striden om oppstandelsen`,en:`Understand the dispute about the resurrection`}},{flag:`de-andre-lost`,points:15,label:{nb:`Finn dem utenfor`,en:`Find the outsiders`}},{flag:`mot-josefus-lost`,points:10,label:{nb:`Prøv vitnene mot Josefus`,en:`Test the witnesses against Josephus`}},{flag:`passet-ikke-lost`,points:20,label:{nb:`Se at han ikke passet`,en:`See that he did not fit`}},{flag:`raadet-lost`,points:10,label:{nb:`Forstå det store rådet`,en:`Understand the great council`}},{flag:`avsluttet`,points:10,label:{nb:`Fullfør dagen med Lukas`,en:`Finish the day with Luke`}},{flag:`spill-stjerner`,points:10,label:{nb:`Finn stjernene`,en:`Find the stars`},side:!0},{flag:`ingen-kom`,points:12,label:{nb:`Bær tollerens innbydelser til alle fire`,en:`Carry the tax collector’s invitations to all four`},side:!0},{flag:`kalender-sett`,points:10,label:{nb:`Se på soluret og månetavla`,en:`Look at the sundial and the moon table`},side:!0},{flag:`retningene-sortert`,points:10,label:{nb:`Sorter de fire retningene`,en:`Sort the four schools`},side:!0}],inventory:[{icon:`✉`,label:{nb:`Innbydelser`,en:`Invitations`},flags:[`innbydelser`],goneWhen:`ingen-kom`}],ambience:[{sound:`market`,x:20,y:13,radius:6},{sound:`garden`,x:5,y:15,radius:6}],goal:[`avsluttet`],solution:`lukas.fariseer.saddukeer.essener.ung.toller.toller.fariseer.saddukeer.essener.ung.toller.samaritan.greker.gutt.gjerdet.soluret.maanetavla.essener.dor-raadskammer.raadsherre.benker.nikodemus.dor-ut-raadskammer.dor-skriverkammer.josefus.notat.moses.daniel.dor-ut-skriverkammer.fire.oppstandelsen.de-andre.mot-josefus.passet-ikke.raadet.lukas`.split(`.`)};export{e as default};